class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0
        cnt_N = cnt_S = cnt_E = cnt_W = 0

        for i, ch in enumerate(s, 1):
            if ch == 'N':
                cnt_N += 1
            elif ch == 'S':
                cnt_S += 1
            elif ch == 'E':
                cnt_E += 1
            else:
                cnt_W += 1

            min_bad = min(
                cnt_S + cnt_W,
                cnt_N + cnt_E,
                cnt_N + cnt_W,
                cnt_S + cnt_E,
            )

            ans = max(ans, i - 2 * max(0, min_bad - k))

        return ans
